    let colorPreferencesCount = input.colorPreferences.reduce(into: [String: Int]()) { $0[$1] = ($0[$1] ?? 0) + 1 }
    guard let mostCommonColor = colorPreferencesCount.first?.key else { return "I couldn't determine your favorite color." }

    // Calculate the average number of clicks per day
    let clicksAverage = input.clicks.average()
    guard let clicksAverageValue = clicksAverage else { return "I couldn't calculate the average number of clicks per day." }

    // Calculate the percentage of positive product reviews
