    let productReviewsTotalCount = input.productReviews.count
    guard let positivePercentage = Double(productReviewsPositiveCount) / Double(productReviewsTotalCount) else { return "I couldn't calculate the percentage of positive product reviews." }

    // Generate the meaningful statement
    return "Based on your input, it seems that you prefer \(mostCommonColor) and tend to click an average of \(clicksAverageValue) times per day. Additionally, \(positivePercentage * 100)% of your product reviews were positive."
}

